from module_adapters._graph_extended_support import Diagram,validate
SOURCE='capsnet-modules/net.py';KEY='capsule_routing'
LINKS=[('b','initial.softmax','in','parameter_operand'),('votes','initial.sum','votes','retained_value'),('initial.squash','agreement','v_initial','initial_state'),('b','expand','in','parameter_operand'),('votes','agreement','votes','retained_value'),('agreement','update','agreement','tensor'),('expand','update','b_initial','initial_state'),('update','couplings.view','in','tensor'),('couplings.restore','sum','couplings','tensor'),('votes','sum','votes','retained_value'),('sum','squash','in','tensor'),('squash','agreement','v_next','loop_recurrence'),('update','update','b_next','loop_recurrence'),('squash','output','in','tensor')]
REQUIRED={'b':dict(parameter='b',storage_kind='parameter',shape='[1152,10]'),'initial.softmax':dict(dim_argument='omitted'),'agreement':dict(expression='(u_predict * v).sum(-1)',vote_reuse=True),'update':dict(expression='b_batch + (u_predict * v).sum(-1)',not_parameter_assignment=True),'couplings.softmax':dict(dim_argument='omitted',flatten_output_caps=True),'squash':dict(epsilon_added=False)}
CONTRACTS=[('AgreementRouting.__init__','nn.Parameter(torch.zeros((input_caps, output_caps)))'),('AgreementRouting.forward','F.softmax(self.b)'),('AgreementRouting.forward','range(self.n_iterations)'),('AgreementRouting.forward','b_batch + (u_predict * v).sum(-1)'),('AgreementRouting.forward','F.softmax(b_batch.view(-1, output_caps))'),('squash','x.pow(2).sum(dim=2)')]
def build():
 d=Diagram(KEY,'Capsule agreement routing',SOURCE,'AgreementRouting.forward','AgreementRouting only, initial routing plus3 refinements; excludes CapsLayer vote weights, primary capsules, task probability and reconstruction heads.',dict(input_caps=1152,output_caps=10,output_dim=16,n_iterations=3,initial_routing_passes=1,total_aggregation_passes=4,learned_initial_logits=True,softmax_dim_argument='omitted',detach_votes=False))
 init=d.ref('AgreementRouting.__init__');sq=d.ref('squash')
 d.input('votes','Fixed votes u_predict','[B,1152,10,16]');d.input('b','Learned initial routing logits b','[1152,10]',kind='parameter',source=init,**{k:v for k,v in REQUIRED['b'].items() if k!='shape'})
 d.stage('initial','Initial routing before loop','[B,10,16]',0,[('softmax','Softmax b / dim omitted','softmax','[1152,10]',REQUIRED['initial.softmax']),('sum','Broadcast c / sum input capsules','sum','[B,10,16]',dict(sum_dim=1)),('squash','Squash capsule vectors','squash','[B,10,16]',dict(epsilon_added=False))],source=[d.entry,sq])
 d.node('expand','Expand SAME b over batch','tensor','[B,1152,10]',0,expression='self.b.expand((batch_size, input_caps, output_caps))')
 d.node('agreement','Unsqueeze v / vote agreement','multiply','[B,1152,10]',1,**REQUIRED['agreement'])
 d.node('update','Update batch routing state','add','[B,1152,10]',2,**REQUIRED['update'])
 d.stage('couplings','Repeat3 / new couplings','[B,1152,10,1]',3,[('view','View batches of output capsules','tensor','[B*1152,10]',dict()),('softmax','Softmax / dim omitted','softmax','[B*1152,10]',REQUIRED['couplings.softmax']),('restore','Restore coupling axes','tensor','[B,1152,10,1]',dict())],iteration_template=True,repeat=3)
 d.node('sum','Weighted vote sum over input caps','sum','[B,10,16]',4,expression='(c * u_predict).sum(dim=1)',sum_dim=1)
 d.node('squash','Squash / source has no epsilon','squash','[B,10,16]',5,source=sq,epsilon_added=False,formula='x * (lengths2 / (1+lengths2) / lengths)')
 for s,t,p,r in LINKS:d.edge(s,t,p,r,ss='left' if r in ('retained_value','loop_recurrence') else 'out',ds='left' if r=='loop_recurrence' or t=='initial.sum' else 'in')
 return d.build(d.entry,'[B,10,16]','CapsuleRouting.md',['Unlike common textbook routing, source b is a learned Parameter initialized to zero and shared across batch. b_batch is per-forward state, not a new Parameter.','Source performs an initial Softmax/sum/squash before the n_iterations loop; selected3 iterations therefore produce four aggregations, not three.','Votes are retained and reused in every agreement and weighted sum; no detach occurs. b_batch and v are loop-carried state.','Both F.softmax calls omit dim; loop reshapes to rows of output_caps, but runtime-dependent legacy dim behavior is preserved rather than silently repaired.','squash divides by lengths with no epsilon in source; shape reasoning does not establish numerical behavior at zero length.'],['Do not draw learned b as a fixed buffer, claim3 total passes, or invent independent parameters per routing round.','Do not include CapsNet classifier/reconstruction in this module-only graph.'])
def validate_ir(ir):return validate(ir,KEY,REQUIRED,LINKS,dict(total_aggregation_passes=4,learned_initial_logits=True,detach_votes=False))
